"use client"

import { useEffect, useMemo, useState } from "react"
import { PauseIcon, PlayIcon, SearchIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { BookPreviewPageView } from "../book-preview-page"
import { DEFAULT_CAPABILITIES, hasSpeechSupport } from "../capabilities"
import { usePdfSheets, type PdfSheet } from "../hooks/use-pdf-sheets"
import { pageSearchText } from "../normalize"
import { useStableHandler } from "../hooks/use-stable-handler"
import type { BookPreviewEngineProps, BookPreviewPage } from "../types"
import { CURL_MAX_PAGES, CURL_PAGE_RATIO, CURL_RASTER_WIDTH } from "./curl-geometry"
import { CurlStage } from "./curl-stage"
import { CurlPdfSheet } from "./curl-pdf-sheet"
import { PdfPreparingBadge } from "./pdf-preparing-badge"
import { FlipSheet } from "./flip-sheet"

type SearchMatch = { key: string; label: string; index: number }

function usePageSpeech({
  usePdf,
  sheets,
  pageIndex,
  current,
}: {
  usePdf: boolean
  sheets: PdfSheet[] | null
  pageIndex: number
  current: BookPreviewPage | undefined
}) {
  const [speaking, setSpeaking] = useState(false)

  useEffect(() => {
    return () => {
      if (typeof window !== "undefined" && "speechSynthesis" in window) {
        window.speechSynthesis.cancel()
      }
    }
  }, [pageIndex])

  const spokenText = usePdf
    ? sheets?.[pageIndex]?.text ?? ""
    : current
      ? pageSearchText(current)
      : ""

  const toggleSpeech = () => {
    if (!hasSpeechSupport() || !spokenText) return
    if (speaking) {
      window.speechSynthesis.cancel()
      setSpeaking(false)
      return
    }
    const utterance = new SpeechSynthesisUtterance(spokenText)
    utterance.onend = () => setSpeaking(false)
    utterance.onerror = () => setSpeaking(false)
    window.speechSynthesis.cancel()
    window.speechSynthesis.speak(utterance)
    setSpeaking(true)
  }

  return { speaking, spokenText, toggleSpeech }
}

function ArchivalSearchControls({
  query,
  usePdf,
  speaking,
  speechDisabled,
  onQueryChange,
  onToggleSpeech,
}: {
  query: string
  usePdf: boolean
  speaking: boolean
  speechDisabled: boolean
  onQueryChange: (query: string) => void
  onToggleSpeech: () => void
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <div className="relative min-w-[12rem] flex-1">
        <SearchIcon className="pointer-events-none absolute top-1/2 left-2 size-4 -translate-y-1/2 text-muted-foreground" />
        <Input
          value={query}
          onChange={(event) => onQueryChange(event.target.value)}
          placeholder={usePdf ? "Search document" : "Search plates"}
          className="pl-8"
          aria-label={usePdf ? "Search document" : "Search plates"}
        />
      </div>
      <Button
        type="button"
        variant={speaking ? "secondary" : "outline"}
        size="sm"
        onClick={onToggleSpeech}
        disabled={speechDisabled}
        aria-pressed={speaking}
        data-book-preview-press
      >
        {speaking ? <PauseIcon data-icon="inline-start" /> : <PlayIcon data-icon="inline-start" />}
        {speaking ? "Stop reading" : "Read page"}
      </Button>
    </div>
  )
}

function ArchivalMatchList({
  query,
  matches,
  usePdf,
  preparing,
  onSelect,
}: {
  query: string
  matches: SearchMatch[]
  usePdf: boolean
  preparing: boolean
  onSelect: (index: number) => void
}) {
  if (!query) return null
  return (
    <div className="flex max-h-24 flex-wrap gap-2 overflow-auto" aria-live="polite">
      {matches.length === 0 ? (
        <p className="text-xs text-muted-foreground">
          {usePdf && preparing ? "Still reading the document\u2026" : "No matches."}
        </p>
      ) : (
        matches.map((match) => (
          <Button
            key={match.key}
            type="button"
            size="xs"
            variant="outline"
            onClick={() => onSelect(match.index)}
            data-book-preview-press
          >
            {match.label}
          </Button>
        ))
      )}
    </div>
  )
}

function ArchivalSheets({
  usePdf,
  sheets,
  pages,
  appearance,
}: {
  usePdf: boolean
  sheets: PdfSheet[] | null
  pages: BookPreviewPage[]
  appearance: BookPreviewEngineProps["appearance"]
}) {
  if (usePdf && sheets) {
    return sheets.map((sheet) => (
      <FlipSheet key={sheet.id}>
        <CurlPdfSheet src={sheet.src} />
      </FlipSheet>
    ))
  }
  return pages.map((page, index) => (
    <FlipSheet key={page.id}>
      <BookPreviewPageView
        page={page}
        appearance={appearance}
        isLeftPage={index % 2 === 1}
      />
    </FlipSheet>
  ))
}

export default function ArchivalCurlEngine({
  source,
  pageIndex,
  appearance,
  soundEnabled,
  reducedMotion,
  onPageChange,
  onReady,
  onError,
}: BookPreviewEngineProps) {
  const [query, setQuery] = useState("")
  const pages = source.pages
  const pdfUrl = source.pdfUrl
  const usePdf = Boolean(pdfUrl) && pages.length === 0
  const current = pages[pageIndex]
  const reportReady = useStableHandler(onReady)
  const reportError = useStableHandler(onError)

  const { sheets, ratio, prepared, preparing } = usePdfSheets({
    pdfUrl,
    enabled: usePdf,
    pageIndex,
    rasterWidth: CURL_RASTER_WIDTH,
    sizing: "uniform",
    // An archival reader that cannot find a word in the document is a viewer.
    extractText: true,
    maxPages: CURL_MAX_PAGES,
    maxPagesMessage: `This document is longer than ${CURL_MAX_PAGES} pages — too heavy for the archival reader, which paints every page up front. Scroll or PDF mode handles it instead.`,
    onError: reportError,
    errorMessage: "This PDF could not be opened for the archival reader.",
  })

  const totalPages = usePdf ? sheets?.length ?? 0 : pages.length

  const matches = useMemo<{ key: string; label: string; index: number }[]>(() => {
    const value = query.trim().toLowerCase()
    if (!value) return []
    if (usePdf) {
      return (sheets ?? [])
        .map((sheet, index) => ({ sheet, index }))
        .filter(({ sheet }) => sheet.text.toLowerCase().includes(value))
        .map(({ sheet, index }) => ({ key: sheet.id, label: `Page ${index + 1}`, index }))
    }
    return pages
      .map((page, index) => ({ page, index }))
      .filter(({ page }) => pageSearchText(page).toLowerCase().includes(value))
      .map(({ page, index }) => ({
        key: page.id,
        label: page.title ?? `Page ${page.pageNumber}`,
        index,
      }))
  }, [pages, query, sheets, usePdf])

  useEffect(() => {
    if (usePdf) {
      if (!sheets) return
      reportReady({
        totalPages: sheets.length,
        capabilities: {
          ...DEFAULT_CAPABILITIES,
          curl: true,
          search: true,
          speech: hasSpeechSupport(),
          // The document brings its own paper; ours would fight it.
          appearance: false,
          thumbnails: true,
          download: Boolean(source.downloadUrl || source.pdfUrl),
        },
      })
      return
    }
    if (pages.length === 0) {
      reportError({ kind: "empty", message: "The archival curl reader needs page data or a PDF." })
      return
    }
    reportReady({
      totalPages: pages.length,
      capabilities: {
        ...DEFAULT_CAPABILITIES,
        curl: true,
        search: true,
        speech: hasSpeechSupport(),
        thumbnails: true,
        download: Boolean(source.downloadUrl),
      },
    })
  }, [
    pages.length,
    reportError,
    reportReady,
    sheets,
    source.downloadUrl,
    source.pdfUrl,
    usePdf,
  ])

  const { speaking, spokenText, toggleSpeech } = usePageSpeech({
    usePdf,
    sheets,
    pageIndex,
    current,
  })

  if (usePdf && !sheets) {
    return (
      <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
        Opening PDF…
      </div>
    )
  }

  return (
    <div className="flex h-full w-full flex-col gap-3 p-4">
      <ArchivalSearchControls
        query={query}
        usePdf={usePdf}
        speaking={speaking}
        speechDisabled={!hasSpeechSupport() || !spokenText}
        onQueryChange={setQuery}
        onToggleSpeech={toggleSpeech}
      />
      <ArchivalMatchList
        query={query}
        matches={matches}
        usePdf={usePdf}
        preparing={preparing}
        onSelect={onPageChange}
      />
      <div className="relative min-h-0 flex-1">
        <CurlStage
          pageIndex={pageIndex}
          pageRatio={usePdf ? ratio ?? CURL_PAGE_RATIO : CURL_PAGE_RATIO}
          canGoPrev={pageIndex > 0}
          canGoNext={pageIndex < Math.max(totalPages, 1) - 1}
          reducedMotion={reducedMotion}
          soundEnabled={soundEnabled}
          contentKey={
            usePdf
              ? `pdf:${sheets?.length ?? 0}`
              : `${appearance}:${pages.map((page) => page.id).join(",")}`
          }
          onPageChange={onPageChange}
          onEngineError={(message) => reportError({ kind: "engine-load", message })}
        >
          <ArchivalSheets
            usePdf={usePdf}
            sheets={sheets}
            pages={pages}
            appearance={appearance}
          />
        </CurlStage>
        {preparing && sheets ? (
          <PdfPreparingBadge prepared={prepared} total={sheets.length} />
        ) : null}
      </div>
    </div>
  )
}
